```cpp
// util.h
#pragma once                           // common include guard.
template <typename T>
T biggest(T a, T b) {                  // full definition visible to includers.
    return (a < b) ? b : a;
}

int count_words(const char* text);     // declaration only.

// util.cpp
#include "util.h"
int count_words(const char* text) { /* ... */ return 0; }   // exactly one definition.

// main.cpp
#include <iostream>
#include "util.h"
int main() {
    std::cout << biggest(3, 7) << '\n';   // instantiates biggest<int> here.
}
```

```bash
g++ -std=c++20 -Wall -c util.cpp main.cpp
g++ util.o main.o -o app
```

